/** An organization role `setRole` may assign. */
export type OrgRole = "member" | "admin" | "owner";

/** One member of an organization, shaped like Better Auth's get-full-organization. */
export interface AuthMember {
  id: string;
  userId: string;
  organizationId: string;
  role: string;
  createdAt: string | null;
  user: { id: string; email: string; name: string | null; image: string | null };
}

export interface AuthSurface {
  /**
   * Ban a user (Better Auth admin plugin semantics): sets `banned`, records
   * the reason, deletes every session, and stamps `qbrev:user` so outstanding
   * JWTs die. You cannot ban yourself.
   */
  ban(userId: string, reason?: string): Promise<void>;
  /**
   * Set a member's role in the caller's active organization (an operator may
   * pass `{ orgId }`). Org-bound callers may assign, and change, roles only
   * at or below their own; the last owner cannot be demoted.
   */
  setRole(userId: string, role: OrgRole, opts?: { orgId?: string }): Promise<void>;
  /**
   * Delete a user account through Better Auth's adapter: memberships,
   * sessions, linked accounts, then the user row. Deleting yourself is always
   * allowed; anyone else follows the org-bound rules above.
   */
  deleteAccount(userId: string): Promise<void>;
  members: {
    /**
     * Members of an organization with their user profile — the caller's active
     * organization by default. Only an operator may name another `orgId`.
     */
    list(orgId?: string): Promise<AuthMember[]>;
  };
}

const HAS_ORG = true;
/** Admin tier per platform role (admin plugin adminRoles; 0 = not an operator). */
const ADMIN_TIERS: Record<string, number> = {"appmanager":1,"sysadmin":2};
/** Organization role rank, lowest = 1 (auth.roleHierarchy). Unlisted roles rank 0. */
const ORG_ROLE_RANKS: Record<string, number> = {"member":1,"admin":2,"owner":3};
const ORG_ROLES: ReadonlySet<string> = new Set(["member","admin","owner"]);

class AuthSurfaceError extends Error {
  readonly code: string;
  readonly statusCode: number;
  constructor(message: string, code: string, statusCode: number) {
    super(message);
    // Rides the action route's ActionError mapping (duck-typed on name).
    this.name = 'ActionError';
    this.code = code;
    this.statusCode = statusCode;
  }
}

function roleNames(role: unknown): string[] {
  if (Array.isArray(role)) return role.filter((r): r is string => typeof r === 'string');
  return typeof role === 'string' ? role.split(',').map((r) => r.trim()).filter(Boolean) : [];
}

function adminTier(role: unknown): number {
  return Math.max(0, ...roleNames(role).map((r) => ADMIN_TIERS[r] ?? 0));
}

function orgRank(role: unknown): number {
  return Math.max(0, ...roleNames(role).map((r) => ORG_ROLE_RANKS[r] ?? 0));
}

const notFound = () => new AuthSurfaceError('User not found.', 'AUTH_SURFACE_NOT_FOUND', 404);

/**
 * Build ctx.auth for one request. `getAuth` returns the (lazy) Better Auth
 * instance; nothing is constructed until a method runs.
 */
export function createAuthSurface(getAuth: () => any, ctx: any, env: any): AuthSurface {
  const authContext = async () => {
    const context = await getAuth().$context;
    if (!context?.adapter || !context?.internalAdapter) {
      throw new AuthSurfaceError('Better Auth context is unavailable.', 'AUTH_SURFACE_UNAVAILABLE', 500);
    }
    return context;
  };

  const caller = () => {
    if (typeof ctx?.userId !== 'string' || !ctx.userId) {
      throw new AuthSurfaceError('ctx.auth requires a signed-in account.', 'AUTH_SURFACE_UNAUTHENTICATED', 401);
    }
    const tier = adminTier(ctx.userRole);
    return { userId: ctx.userId as string, tier, operator: tier > 0 };
  };

  const requireOrg = (who: { operator: boolean }, orgId?: string): string => {
    if (orgId !== undefined && !who.operator && orgId !== ctx.activeOrgId) {
      throw new AuthSurfaceError('Only an operator may act on another organization.', 'AUTH_SURFACE_OUT_OF_SCOPE', 403);
    }
    const resolved = orgId ?? ctx.activeOrgId;
    if (typeof resolved !== 'string' || !resolved) {
      throw new AuthSurfaceError('No active organization.', 'AUTH_SURFACE_NO_ORG', 403);
    }
    return resolved;
  };

  const findMember = async (c: any, organizationId: string, userId: string) =>
    c.adapter.findOne({
      model: 'member',
      where: [
        { field: 'organizationId', value: organizationId },
        { field: 'userId', value: userId },
      ],
    });

  const stampUser = async (userId: string) => {
    // auth.jwt.revocationCheck is not 'kv': nothing reads a revocation entry.
    void userId;
  };

  const stampMember = async (userId: string, organizationId: string) => {
    void userId;
    void organizationId;
    await stampUser(userId);
  };

  /**
   * The org-bound gate for account-wide effects (ban, delete). Returns once
   * the caller may act on `targetId`; throws 404 / 403 otherwise.
   */
  const assertMayActOnAccount = async (c: any, who: ReturnType<typeof caller>, targetId: string) => {
    const target = await c.internalAdapter.findUserById(targetId);
    if (who.operator) {
      if (!target) throw notFound();
      if (adminTier((target as any).role) > who.tier) {
        throw new AuthSurfaceError('Target holds a higher platform role.', 'AUTH_SURFACE_ROLE_CEILING', 403);
      }
      return target;
    }
    if (!HAS_ORG) {
      throw new AuthSurfaceError('Only an operator may act on another account.', 'AUTH_SURFACE_OUT_OF_SCOPE', 403);
    }
    const organizationId = requireOrg(who);
    // Not a member of the caller's organization reads as "not found" — the
    // caller learns nothing about accounts outside its tenant.
    const membership = target ? await findMember(c, organizationId, targetId) : null;
    if (!target || !membership) throw notFound();
    if (adminTier((target as any).role) > 0) {
      throw new AuthSurfaceError('Target is a platform operator.', 'AUTH_SURFACE_OUT_OF_SCOPE', 403);
    }
    if (orgRank((membership as any).role) > orgRank(ctx.orgRole ?? ctx.roles)) {
      throw new AuthSurfaceError('Target holds a higher organization role.', 'AUTH_SURFACE_ROLE_CEILING', 403);
    }
    const memberships = await c.adapter.findMany({ model: 'member', where: [{ field: 'userId', value: targetId }], limit: 2 });
    if ((memberships as any[]).some((m) => m.organizationId !== organizationId)) {
      throw new AuthSurfaceError('Target also belongs to another organization — only an operator may change the account.', 'AUTH_SURFACE_OUT_OF_SCOPE', 403);
    }
    return target;
  };

  const surface: any = {
    async deleteAccount(userId: string) {
      const who = caller();
      const c = await authContext();
      if (userId !== who.userId) {
        await assertMayActOnAccount(c, who, userId);
      } else if (!(await c.internalAdapter.findUserById(userId))) {
        throw notFound();
      }
      if (HAS_ORG) {
        await c.adapter.deleteMany({ model: 'member', where: [{ field: 'userId', value: userId }] });
      }
      await c.internalAdapter.deleteUserSessions(userId);
      await c.internalAdapter.deleteUser(userId);
      await stampUser(userId);
    },
  };

  surface.ban = async (userId: string, reason?: string) => {
    const who = caller();
    if (userId === who.userId) {
      throw new AuthSurfaceError('You cannot ban yourself.', 'AUTH_SURFACE_SELF', 400);
    }
    const c = await authContext();
    await assertMayActOnAccount(c, who, userId);
    await c.internalAdapter.updateUser(userId, {
      banned: true,
      banReason: typeof reason === 'string' && reason ? reason : 'No reason',
      banExpires: null,
      updatedAt: new Date(),
    });
    await c.internalAdapter.deleteUserSessions(userId);
    await stampUser(userId);
  };

  surface.setRole = async (userId: string, role: OrgRole, opts?: { orgId?: string }) => {
    const who = caller();
    const roles = roleNames(role);
    if (roles.length === 0 || roles.some((r) => !ORG_ROLES.has(r))) {
      throw new AuthSurfaceError('Unknown organization role: ' + String(role) + '.', 'AUTH_SURFACE_INVALID_ROLE', 400);
    }
    const organizationId = requireOrg(who, opts?.orgId);
    const c = await authContext();
    const membership: any = await findMember(c, organizationId, userId);
    if (!membership) throw notFound();
    const target = await c.internalAdapter.findUserById(userId);
    if (!target) throw notFound();
    if (who.operator && adminTier(target.role) > who.tier) {
      throw new AuthSurfaceError('Target holds a higher platform role.', 'AUTH_SURFACE_ROLE_CEILING', 403);
    }
    if (!who.operator) {
      const own = orgRank(ctx.orgRole ?? ctx.roles);
      if (orgRank(role) > own || orgRank(membership.role) > own) {
        throw new AuthSurfaceError('Cannot assign or change a role above your own.', 'AUTH_SURFACE_ROLE_CEILING', 403);
      }
      if (adminTier((target as any).role) > 0) {
        throw new AuthSurfaceError('Target is a platform operator.', 'AUTH_SURFACE_OUT_OF_SCOPE', 403);
      }
    }
    if (typeof c.adapter.$qbSetMemberRole !== 'function') {
      throw new AuthSurfaceError('Guarded auth adapter is unavailable.', 'AUTH_SURFACE_UNAVAILABLE', 500);
    }
    const updated = await c.adapter.$qbSetMemberRole({ membership, organizationId, userId, targetRole: target.role ?? null, role: roles.join(',') });
    if (!updated) {
      throw new AuthSurfaceError('The membership changed or this would remove the last owner.', 'AUTH_SURFACE_LAST_OWNER', 409);
    }
    await stampMember(userId, organizationId);
  };

  surface.members = {
    async list(orgId?: string): Promise<AuthMember[]> {
      const who = caller();
      const organizationId = requireOrg(who, orgId);
      const c = await authContext();
      const members: any[] = [];
      for (let offset = 0; ; offset += 100) {
        const page = await c.adapter.findMany({
          model: 'member',
          where: [{ field: 'organizationId', value: organizationId }],
          limit: 100,
          offset,
          sortBy: { field: 'createdAt', direction: 'asc' },
        });
        members.push(...(page as any[]));
        if ((page as any[]).length < 100) break;
      }
      const ids = [...new Set(members.map((m) => m.userId))];
      const users = new Map<string, any>();
      for (let i = 0; i < ids.length; i += 90) {
        const chunk = ids.slice(i, i + 90);
        const rows = await c.adapter.findMany({ model: 'user', where: [{ field: 'id', operator: 'in', value: chunk }], limit: chunk.length });
        for (const u of rows as any[]) users.set(u.id, u);
      }
      return members.map((m) => {
        const u = users.get(m.userId);
        const created = m.createdAt instanceof Date ? m.createdAt.toISOString() : m.createdAt ?? null;
        return {
          id: m.id,
          userId: m.userId,
          organizationId: m.organizationId,
          role: m.role,
          createdAt: created,
          user: { id: m.userId, email: u?.email ?? '', name: u?.name ?? null, image: u?.image ?? null },
        };
      });
    },
  };

  return surface as AuthSurface;
}

